        frame.store("_a_meal_word_misspelt", { let __signature_3480 = Signature { name: "_a_meal_word_misspelt".into(), positional: vec!["clean".into(),"words".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3482 = Value::dict(); __attrs_3482.dict_set(Value::from("__doc__"), Value::from("Put a meal word typed at speed back in the line, in `clean` as well as the reading.\n\n    It is repaired in `clean` for the reason the \"docs\" repair is: the kitchen's rows are keyed\n    on the meal, so a reading fixed on its own would leave the reply where it was. The slot is\n    what makes it safe - the word in front has to be the preposition a meal goes behind, and\n    what follows has to be the end of the line or the time it is for - and that is what keeps a\n    name out of it (\"tae is coming over\", \"me and tae went out\"). A name can sit behind \"for\"\n    (\"im waiting for tae\" reads as the meal), so it is the position, not the name, that decides.\n    "))?; __attrs_3482.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3483 = Value::dict(); __attrs_3482.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3479 = Frame::module(frame.globals.clone()); let mut __function_3481 = NativeFunction::qualified_with_attrs("_a_meal_word_misspelt".into(), "_a_meal_word_misspelt".into(), "bot.understanding.normalize".into(), __attrs_3482, move |rt, args| __py_169::_a_meal_word_misspelt(rt, __closure_3479.clone(), &__signature_3480, args)); __function_3481 })?;
